yakit.AutoInitYakit()

targets := cli.String("targets")
data := targets
targets = str.Split(targets, "\n") 
api_key := cli.String("aizhan_key")
file_path := cli.String("file_path")

site := `https://apistore.aizhan.com/baidurank/siteinfos/`+api_key+`?domains=`

yakit.EnableTable("IP/域名 百度权重查询结果", ["主机","PC端权重","手机端权重"])

def WeightQuery(target,api_key){
    //yakit.Info(target)
    Query = site + target
    rsp,_ :=http.Get(Query)
    raw,_ := io.ReadAll(rsp.Body)

    //处理json数据
    result:=json.loads(string(raw))
    dump(result)
    data := result["data"]
    data_success :=  data["success"]
    data_weight := data_success[0]

    domain := data_weight["domain"]
    pc_br := data_weight["pc_br"]
    m_br := data_weight["m_br"]
    if( pc_br > 0 || m_br > 0){
        ResultOut(target,pc_br,m_br)
    }
    sleep(1)
}

def ResultOut(target,pc_weight,mobile_weight){
    data := make(map[string]var)
    data["主机"] = target
    data["PC端权重"] = pc_weight
    data["手机端权重"] = mobile_weight
    yakit.Output(yakit.TableData("IP/域名 百度权重查询结果", data))
}

def DomainGet(url){
    if str.IsHttpURL(url){
        url = str.ReplaceAll(url, "http://", "")
        url = str.ReplaceAll(url, "https://", "")
    }
    if str.Contains(url, "/"){
        url = str.Split(url, "/")[0]
    }
    return url
}

if data == "" && file_path == "" {
    yakit.Info("大佬，请输入查询目标或选择目标文件路径")
}else{
    if file_path != "" && !file.IsFile(file_path){
        yakit.Info("大佬，目标文件不存在，看一下")
    }else{
        if file_path != ""{
            fp = file.ReadLines(file_path)
            if len(fp) == 0 {
                yakit.Info("大佬，目标文件啥都没有，看了个寂寞")
            }else{
                if len(targets) != 0 {
                    for _,target = range(targets){
                        if target == "" {continue}
                        target = DomainGet(target)
                        WeightQuery(target,api_key)
                    }
                }
                for _,target = range(fp){
                    if target == "" {continue}
                    target = DomainGet(target)
                    WeightQuery(target,api_key)
                }
            }
        }else{
            for _,target = range(targets){
                if target == "" {continue}
                target = DomainGet(target)
                WeightQuery(target,api_key)
            }
        }
    }
}
